import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int s = in.nextInt();
        int t = in.nextInt();
        System.out.println(n * s + " " + n * s * t);
    }
}

starter.cpp:
#include <iostream>
using namespace std;

int main() {
    int n, s, t;
    cin >> n >> s >> t;
    cout << n * s << " " << n * s * t << endl;
    return 0;
}

