import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long s = in.nextLong();
        long t = in.nextLong();
        System.out.println(n * s);
        System.out.println(n * s * t);
    }
}

